ALTER TABLE assessment_campaigns ADD COLUMN opens_at timestamptz NOT NULL DEFAULT now(),ADD COLUMN closes_at timestamptz NOT NULL DEFAULT now()+interval '30 days',ADD COLUMN candidate_days integer NOT NULL DEFAULT 5,ADD COLUMN welcome_message text NOT NULL DEFAULT '';
CREATE TABLE public.pipeline_candidates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES assessment_campaigns(id),name text NOT NULL,email text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(campaign_id,email));GRANT SELECT,INSERT ON pipeline_candidates TO authenticated;GRANT ALL ON pipeline_candidates TO service_role;ALTER TABLE pipeline_candidates ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.pipeline_responses(attempt_id uuid NOT NULL REFERENCES assessment_attempts(id),item_id text NOT NULL,answer text NOT NULL,time_seconds integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(attempt_id,item_id));GRANT SELECT ON pipeline_responses TO authenticated;GRANT ALL ON pipeline_responses TO service_role;ALTER TABLE pipeline_responses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.pipeline_scores(attempt_id uuid NOT NULL REFERENCES assessment_attempts(id),score_type text NOT NULL CHECK(score_type IN ('item','section','ksao','composite')),score_key text NOT NULL,value numeric NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(attempt_id,score_type,score_key));GRANT SELECT ON pipeline_scores TO authenticated;GRANT ALL ON pipeline_scores TO service_role;ALTER TABLE pipeline_scores ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.pipeline_rater_scores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL REFERENCES assessment_attempts(id),item_id text NOT NULL,rater_id uuid NOT NULL,ratings jsonb NOT NULL,comment text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(attempt_id,item_id,rater_id));GRANT SELECT ON pipeline_rater_scores TO authenticated;GRANT ALL ON pipeline_rater_scores TO service_role;ALTER TABLE pipeline_rater_scores ENABLE ROW LEVEL SECURITY;
ALTER TABLE assessment_attempts ADD COLUMN candidate_id uuid UNIQUE REFERENCES pipeline_candidates(id),ADD COLUMN started_at timestamptz,ADD COLUMN auto_scored_at timestamptz,ADD COLUMN completed_sections jsonb NOT NULL DEFAULT '[]',ADD COLUMN question_order jsonb NOT NULL DEFAULT '[]',ADD COLUMN option_order jsonb NOT NULL DEFAULT '{}',ADD COLUMN accommodation_status text NOT NULL DEFAULT 'none',ADD COLUMN section_times jsonb NOT NULL DEFAULT '{}',ADD COLUMN practice_completed jsonb NOT NULL DEFAULT '[]';
ALTER TABLE hiring_decisions ADD COLUMN outcome text,ADD COLUMN reason text;
CREATE POLICY candidate_read ON pipeline_candidates FOR SELECT TO authenticated USING(org_can('results',(SELECT battery_id FROM assessment_campaigns WHERE id=campaign_id)));CREATE POLICY candidate_insert ON pipeline_candidates FOR INSERT TO authenticated WITH CHECK(org_can('campaigns'));
CREATE POLICY response_read ON pipeline_responses FOR SELECT TO authenticated USING(org_can('results',(SELECT battery_id FROM assessment_attempts WHERE id=attempt_id)));
CREATE POLICY score_read ON pipeline_scores FOR SELECT TO authenticated USING(org_can('results',(SELECT battery_id FROM assessment_attempts WHERE id=attempt_id)));
CREATE POLICY rater_score_read ON pipeline_rater_scores FOR SELECT TO authenticated USING(org_can('results',(SELECT battery_id FROM assessment_attempts WHERE id=attempt_id)) OR (rater_id=auth.uid() AND org_active(auth.uid())));
REVOKE ALL ON pipeline_candidates,pipeline_responses,pipeline_scores,pipeline_rater_scores FROM anon;REVOKE INSERT,UPDATE,DELETE ON pipeline_responses,pipeline_scores,pipeline_rater_scores FROM authenticated;REVOKE UPDATE,DELETE ON pipeline_candidates FROM authenticated;
CREATE FUNCTION public.pipeline_campaign_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.closes_at<=NEW.opens_at OR NEW.candidate_days NOT BETWEEN 1 AND 365 THEN RAISE EXCEPTION 'Invalid campaign dates or window';END IF;IF NOT EXISTS(SELECT 1 FROM assessment_batteries WHERE id=NEW.battery_id AND status='approved' AND approved_at IS NOT NULL AND approved_by IS NOT NULL) AND NOT (coalesce(auth.role(),'')='service_role' AND EXISTS(SELECT 1 FROM assessment_batteries WHERE id=NEW.battery_id AND status='approved' AND (payload->>'fictional')::boolean)) THEN RAISE EXCEPTION 'Recorded HR approval required';END IF;IF TG_OP='UPDATE' AND NEW.battery_id<>OLD.battery_id THEN RAISE EXCEPTION 'Campaign battery version immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER pipeline_campaign_guard BEFORE INSERT OR UPDATE ON assessment_campaigns FOR EACH ROW EXECUTE FUNCTION pipeline_campaign_guard();
CREATE FUNCTION public.pipeline_launch(v jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid;BEGIN IF NOT org_can('campaigns',(v->>'battery_id')::uuid) THEN RAISE EXCEPTION 'HR access required';END IF;INSERT INTO assessment_campaigns(battery_id,name,opens_at,closes_at,candidate_days,welcome_message) VALUES((v->>'battery_id')::uuid,v->>'name',(v->>'opens_at')::timestamptz,(v->>'closes_at')::timestamptz,(v->>'candidate_days')::integer,v->>'welcome_message') RETURNING id INTO cid;RETURN cid;END $$;
CREATE OR REPLACE FUNCTION public.org_can(cap text,rid uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT org_has_role(auth.uid(),'admin') OR CASE cap WHEN 'people' THEN false WHEN 'campaigns' THEN org_has_role(auth.uid(),'hr') WHEN 'approve' THEN org_has_role(auth.uid(),'hr') WHEN 'results' THEN org_has_role(auth.uid(),'hr') OR org_assigned(auth.uid(),rid,'hiring_manager') WHEN 'decision' THEN org_assigned(auth.uid(),rid,'hiring_manager') WHEN 'analysis' THEN org_has_role(auth.uid(),'analyst') WHEN 'fairness' THEN org_has_role(auth.uid(),'analyst') OR org_has_role(auth.uid(),'hr') WHEN 'sme' THEN org_assigned(auth.uid(),rid,'sme') WHEN 'score' THEN org_assigned(auth.uid(),rid,'rater') ELSE false END $$;
CREATE FUNCTION public.pipeline_invite(cid uuid,v jsonb,hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c assessment_campaigns;pid uuid;aid uuid;BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT * INTO c FROM assessment_campaigns WHERE id=cid;IF NOT org_can('campaigns',c.battery_id) THEN RAISE EXCEPTION 'HR access required';END IF;IF c.closes_at<=now() THEN RAISE EXCEPTION 'Campaign closed';END IF;INSERT INTO pipeline_candidates(campaign_id,name,email) VALUES(cid,v->>'name',lower(v->>'email')) RETURNING id INTO pid;INSERT INTO assessment_attempts(battery_id,campaign_id,candidate_id,name,token_hash,expires_at) VALUES(c.battery_id,cid,pid,v->>'name',hash,least(now()+make_interval(days=>c.candidate_days),c.closes_at)) RETURNING id INTO aid;RETURN aid;END $$;
CREATE FUNCTION public.pipeline_server_invite(cid uuid,v jsonb,hash text,actor uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Server action required';END IF;PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);RETURN pipeline_invite(cid,v,hash);END $$;
CREATE FUNCTION public.pipeline_hiring_decision(aid uuid,outcome text,reason text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a assessment_attempts;BEGIN SELECT * INTO a FROM assessment_attempts WHERE id=aid;IF NOT org_can('decision',a.battery_id) OR a.status<>'scored' THEN RAISE EXCEPTION 'Assigned manager and complete scores required';END IF;IF outcome NOT IN ('advance','hold','reject') OR btrim(reason)='' THEN RAISE EXCEPTION 'Decision and reason required';END IF;INSERT INTO hiring_decisions(attempt_id,decision,note,outcome,reason) VALUES(aid,CASE outcome WHEN 'advance' THEN 'hire' WHEN 'reject' THEN 'decline' ELSE 'hold' END,reason,outcome,reason);RETURN true;END $$;
REVOKE ALL ON FUNCTION pipeline_campaign_guard(),pipeline_launch(jsonb),pipeline_invite(uuid,jsonb,text),pipeline_server_invite(uuid,jsonb,text,uuid),pipeline_hiring_decision(uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION pipeline_launch(jsonb),pipeline_hiring_decision(uuid,text,text) TO authenticated;GRANT EXECUTE ON FUNCTION pipeline_server_invite(uuid,jsonb,text,uuid) TO service_role;
CREATE TRIGGER audit_pipeline_candidates AFTER INSERT ON pipeline_candidates FOR EACH ROW EXECUTE FUNCTION org_audit();CREATE TRIGGER audit_pipeline_ratings AFTER INSERT OR UPDATE ON pipeline_rater_scores FOR EACH ROW EXECUTE FUNCTION org_audit();